CREATE TABLE `scalar_dynamic` (
  `id` int NOT NULL,
  `ti` tinyint DEFAULT NULL,
  `sm` smallint DEFAULT NULL,
  `med` mediumint DEFAULT NULL,
  `si` int DEFAULT NULL,
  `bi` bigint DEFAULT NULL,
  `bu` bigint unsigned DEFAULT NULL,
  `d` decimal(65,30) DEFAULT NULL,
  `f` float DEFAULT NULL,
  `x` double DEFAULT NULL,
  `bits` bit(64) DEFAULT NULL,
  `y` year DEFAULT NULL,
  `dt` date DEFAULT NULL,
  `tm` time(6) DEFAULT NULL,
  `ts` timestamp(6) NULL DEFAULT NULL,
  `dd` datetime(6) DEFAULT NULL,
  `ch` char(8) COLLATE utf8mb4_bin DEFAULT NULL,
  `v` varchar(300) COLLATE utf8mb4_bin DEFAULT NULL,
  `b` binary(5) DEFAULT NULL,
  `vb` varbinary(300) DEFAULT NULL,
  `e` enum('','界','a,b') COLLATE utf8mb4_bin DEFAULT NULL,
  `s` set('界','a') COLLATE utf8mb4_bin DEFAULT NULL,
  `j` json DEFAULT NULL,
  `g` point DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;
